"""The worksheets: exercise.json texts and the pictures (prompt.svg) of some of them."""
from icons import *
from lib import text, f


def svg(w, h, inner, bg="#ffffff"):
    return (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}">'
            f'<rect width="{w}" height="{h}" rx="24" fill="{bg}"/>{inner}</svg>\n')


def box(x, y, w, h, col="#455a64", fill="#fff"):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="16" fill="{fill}" stroke="{col}" stroke-width="6" stroke-dasharray="14 8"/>'


# ---------------------------------------------------------------- pictures

def name2(x, name, size=36):
    """A name under a picture, on two lines when it is long."""
    if len(name) <= 14 or " " not in name:
        return text(x, 355, name, size, "#263238")
    a, b = name.rsplit(" ", 1)
    return text(x, 325, a, size, "#263238") + text(x, 370, b, size, "#263238")


def pic_leaf():
    s = g(leaf(), 800, 200, 3.0, rot=20)
    for y in (140, 220, 300):
        s += f'<path d="M180 {y} Q300 {y-30} 420 {y} T660 {y}" fill="none" stroke="#90caf9" stroke-width="10" stroke-linecap="round"/>'
    s += text(800, 470, "ένα φύλλο στον άνεμο", 56, "#263238")
    return svg(1200, 560, s, "#e3f2fd")


def pic_three_devices():
    s = ""
    items = [("α", 220, g(battery(130, 64), 0, 40) + g(bulb(True), 0, -20, 0.8)),  # a torch-like: battery and bulb
             ("β", 600, g(fan_stand(), 0, 10, 0.55) + g(fan_blades(), 0, -12, 0.55)),
             ("γ", 980, g(toy_car(), 0, 10, 1.1) + g(key_wind(), -10, -28, 0.5))]
    names = ["φακός με μπαταρία", "ηλεκτρικός ανεμιστήρας", "κουρδισμένο παιχνίδι"]
    for (letter, x, icon), name in zip(items, names):
        s += f'<rect x="{x-170}" y="30" width="340" height="360" rx="24" fill="#f5f5f5" stroke="#90a4ae" stroke-width="6"/>'
        s += g(icon, x, 190)
        s += text(x - 140, 80, letter, 64, "#c62828", "middle")
        s += name2(x, name)
    return svg(1200, 420, s)


def pic_spring():
    s = '<rect x="80" y="350" width="1040" height="30" rx="10" fill="#8d6e63"/><rect x="100" y="250" width="40" height="100" rx="8" fill="#78909c"/>'
    s += g(spring(240, 7, 34), 270, 300) + '<rect x="383" y="258" width="20" height="84" rx="6" fill="#455a64"/>'
    s += g(paper_ball(34), 440, 316)
    s += arrow(640, 240, 940, 240, "#455a64", 14, 36)
    s += text(790, 200, "αφήνουμε το ελατήριο", 44, "#263238")
    s += text(600, 440, "πιεσμένο ελατήριο και χάρτινο μπαλάκι", 40, "#263238", "middle")
    return svg(1200, 480, s, "#fff8e1")


def pic_chain(labels, top=None):
    """Three dashed boxes with arrows between them, with small pictures."""
    s = ""
    xs = [60, 460, 860]
    for x in xs:
        s += box(x, 250, 280, 120)
    s += arrow(350, 310, 450, 310, "#455a64", 12, 28) + arrow(750, 310, 850, 310, "#455a64", 12, 28)
    s += top
    for x, lab in zip(xs, labels):
        s += text(x + 140, 200, lab, 38, "#263238")
    return svg(1200, 400, s)


def pic_circuit():
    top = g(battery(150, 80), 200, 100, 1.0) + g(bulb(True), 1000, 80, 0.8) + g(
        '<path d="M-90 0 Q-45 -30 0 0 T90 0" fill="none" stroke="#455a64" stroke-width="10" stroke-linecap="round"/>', 600, 100)
    return pic_chain(["μπαταρία", "καλώδια", "λαμπάκι"], top)


def pic_solar():
    top = g(sun(26, 8), 200, 100, 1.0) + g(panel(), 600, 90, 0.6) + g(g(fan_stand(), 0, 10, 0.4) + g(fan_blades(), 0, -6, 0.4), 1000, 100)
    return pic_chain(["Ήλιος", "φωτοβολταϊκό πάνελ", "ανεμιστηράκι"], top)


def pic_degr_devices():
    s = ""
    items = [("α", 220, g(fan_stand(), 0, 10, 0.6) + g(fan_blades(), 0, -14, 0.6), "ηλεκτρικός ανεμιστήρας"),
             ("β", 600, g(truck(), 0, 20, 0.6), "φορτηγό με πετρέλαιο"),
             ("γ", 980, g(glow(70), 0, -8) + g(bulb(True), 0, 0, 0.9), "ηλεκτρικός λαμπτήρας")]
    for letter, x, icon, name in items:
        s += f'<rect x="{x-170}" y="30" width="340" height="360" rx="24" fill="#f5f5f5" stroke="#90a4ae" stroke-width="6"/>'
        s += g(icon, x, 190)
        s += text(x - 140, 80, letter, 64, "#c62828", "middle")
        s += name2(x, name)
    return svg(1200, 420, s)


def pic_day_table():
    rows = [("δραστηριότητα", "ενέργεια σε μία ώρα", "ώρες"), ("ύπνος", "250 kJ", "8"), ("διάβασμα", "400 kJ", "3"),
            ("περπάτημα", "600 kJ", "2"), ("ποδόσφαιρο", "1000 kJ", "1")]
    s = ""
    for i, (a, b, c) in enumerate(rows):
        y = 70 + i * 90
        head = i == 0
        s += f'<rect x="40" y="{y-56}" width="1120" height="80" fill="{"#c5e1a5" if head else ("#f1f8e9" if i % 2 else "#fff")}" stroke="#8bc34a" stroke-width="3"/>'
        sz = 40 if head else 46
        s += text(70, y, a, sz, "#263238", "start") + text(620, y, b, sz, "#263238", "start") + text(1040, y, c, sz, "#263238", "start")
    return svg(1200, 480, s)


def pic_foods():
    foods = [("ρύζι", rice, 1500), ("μήλο", apple, 200), ("λάδι", oil_bottle, 3800), ("ψωμί", bread, 1050), ("γάλα", milk, 300)]
    s = ""
    for i, (n, ic, kj) in enumerate(foods):
        x = 120 + i * 230
        s += f'<rect x="{x-100}" y="30" width="200" height="330" rx="20" fill="#f5f5f5" stroke="#90a4ae" stroke-width="5"/>'
        s += g(ic(), x, 150, 0.8)
        s += text(x, 270, n, 44, "#263238") + text(x, 330, f"{kj} kJ", 40, "#6a1b9a")
    return svg(1200, 400, s)


